mapper.select:
SELECT  primary_key as quotationCode ,type , quotation_name, quotation_number,
         buyer, seller, customer_code, enterprise_code as ownedEnterpriseCode,
         sell_quotation_belong as userCode, user_name, language, payment_strategy,product_grade, column_titles,
         amount_title, product_detail,clauses_chs,clauses_en,quotation_time, state,
data_version,
sell_enquiry,sell_filing,son_enterprise_code,delete_flag,returned,business_belong
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'

    AND sell_quotation_belong IN

        #{userCode}



    AND quotation_number LIKE '%'|| #{quotationNumber}||'%'


    AND customer_code = #{customerDataCode}


    AND state IN

        #{state}



    AND quotation_time >= #{quotationTimePreDate}


    AND quotation_time <= #{quotationTimePostDate}


    ${dataScopeParams.dataScope}


    AND business_belong = #{businessBelong}

ORDER BY create_time DESC

SELECT  primary_key as quotationCode ,type , quotation_name, quotation_number,
buyer, seller, customer_code, enterprise_code as ownedEnterpriseCode,
sell_quotation_belong as userCode, user_name, language, payment_strategy,product_grade, column_titles,
amount_title, product_detail,clauses_chs,clauses_en,quotation_time, temp_data,state,
data_version,
sell_enquiry,sell_filing,buyer_quotation,sign_areas,son_enterprise_code,returned,delete_flag,business_belong
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND primary_key = #{quotationCode}

    AND delete_flag= 'f'


    ${dataScopeParams.dataScope}

mapper.delete:
DELETE FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND primary_key = #{quotationCode}

mapper.update:
UPDATE ${tableName}
SET temp_data = NULL
WHERE
enterprise_code= #{model.ownedEnterpriseCode}
AND primary_key = #{model.quotationCode}
AND temp_data IS NOT NULL

UPDATE ${tableName}
SET temp_data = #{model.tempData},
    son_enterprise_code = #{model.sonEnterpriseCode}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.quotationCode}

UPDATE ${tableName}
SET temp_data           = #{model.tempData},
    quotation_number = #{number},
    son_enterprise_code = #{model.sonEnterpriseCode}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.quotationCode}

