FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND customer_code = #{customerCode}
  AND primary_key != #{excludeQuotationCode}
  AND quotation_number = #{quotationNumber}
  AND delete_flag = 'f'

