    buyer = #{model.buyer},
    state = #{model.state},
    temp_data = NULL,
    buyer_quotation = #{model.buyerQuotation},
    quotation_time = #{model.quotationTime},
    son_enterprise_code = #{model.sonEnterpriseCode},
    returned =  #{model.returned},
    data_version = #{model.dataVersion}
WHERE
    enterprise_code= #{model.ownedEnterpriseCode}
  AND primary_key = #{model.quotationCode}
  AND data_version =  #{clientDataVersion}

