mapper.select:
SELECT COALESCE(SUM(
    CAST(
        COALESCE(
            (product_detail::json->>'productAmount')::numeric,
            0
        ) AS NUMERIC
    )
), 0)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND state = 'DEAL'
  AND create_time IS NOT NULL
  AND create_time >= #{startDate}
  AND create_time <= #{endDate}

    ${dataScopeParams.dataScope}
